declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('guru');$pdo=db();$stmt=$pdo->prepare("SELECT COUNT(*) FROM students WHERE status='aktif'");$stmt->execute();$studentCount=(int)$stmt->fetchColumn();$stmt=$pdo->prepare('SELECT COUNT(*) FROM daily_student_reports WHERE teacher_id=? AND tanggal=CURDATE()');$stmt->execute([$user['id']]);$daily=(int)$stmt->fetchColumn();$stmt=$pdo->prepare('SELECT COUNT(*) FROM laporan_tahsin_tahfidz WHERE teacher_id=? AND tanggal=CURDATE()');$stmt->execute([$user['id']]);$scores=(int)$stmt->fetchColumn();$recent=$pdo->prepare('SELECT d.*,s.nama_lengkap FROM daily_student_reports d JOIN students s ON s.id=d.student_id WHERE d.teacher_id=? ORDER BY d.updated_at DESC LIMIT 7');$recent->execute([$user['id']]);$recent=$recent->fetchAll();$pageTitle='Dashboard Guru';require ROOT_PATH.'/includes/header.php';?>
